// Puts a company's factory together: its products, the extensions and kits
// it uses, and what they add (parts, settings, the agents' guides), with
// everything that does not fit said in plain words before anything starts.
import { builderSettings } from "../agents/builder-settings.js";
import { modelSettings } from "../agents/model-setting.js";
import { updateSettings, usageFolderSettings, usageSettings, } from "../agents/usage-settings.js";
import { withBackendAddress } from "../parts/addresses.js";
import { checkParts, inStartOrder } from "../parts/part.js";
import { checkGroups } from "../settings/setting-groups.js";
import { slotsOf } from "./slots.js";
import { ownExtensionsSettings } from "./team.js";
export function assembleFactory(company, products, available) {
    const problems = [];
    const extensions = chosenExtensions(company, available, problems);
    const tracker = company.tracker;
    if (tracker !== "none" &&
        !extensions.some((e) => e.tracker && e.id === tracker))
        problems.push(`work is tracked in "${tracker}", but no add-on that is on tracks work there`);
    const kits = chosenKits(company, available, problems);
    const known = products.flatMap((product) => {
        const kit = kits.find((k) => k.kind === product.kind);
        if (kit)
            return [withKit(product, kit)];
        problems.push(`"${product.id}" is a ${product.kind}, but the company uses no kit for that kind`);
        return [];
    });
    problems.push(...dependencyProblems(known));
    const parts = allParts(known, kits, extensions);
    const settings = [
        modelSettings,
        builderSettings,
        usageSettings,
        usageFolderSettings,
        updateSettings,
        ownExtensionsSettings,
        ...extensions.flatMap((extension) => extension.settings),
    ];
    problems.push(...checkParts(parts), ...checkGroups(settings, parts.map((part) => part.id)));
    const guides = [
        ...extensions.flatMap((extension) => extension.guides),
        ...kits.flatMap((kit) => kit.guides),
    ];
    return {
        company,
        products: known,
        extensions,
        kits,
        parts,
        settings,
        guides,
        problems,
    };
}
// The core extensions, unless the company switched one off, then the
// add-ons it named.
function chosenExtensions(company, available, problems) {
    const named = (id) => available.extensions.some((e) => e.id === id);
    for (const id of [...company.extensions, ...company.without])
        if (!named(id))
            problems.push(`there is no extension "${id}"`);
    const chosen = available.extensions.filter((extension) => extension.core
        ? !company.without.includes(extension.id)
        : company.extensions.includes(extension.id));
    problems.push(...extensionProblems(available.extensions, chosen, company));
    return chosen;
}
const SLOT_WORDS = {
    code: "where the code lives",
    tasks: "where the tasks are kept",
};
// An extension whose needs are not installed, or that is always needed and
// was removed: the factory does not start, and says why.
function extensionProblems(all, chosen, company) {
    const nameOf = (id) => all.find((e) => e.id === id)?.name ?? id;
    const unfilled = slotsOf(all, company).filter((s) => s.fillers.length === 0);
    return [
        ...all
            .filter((e) => e.always && company.without.includes(e.id))
            .map((e) => `${e.name} is always needed, so it cannot be removed`),
        ...chosen.flatMap((extension) => unfilled
            .filter((one) => extension.slots.includes(one.slot))
            .map((one) => `${extension.name} uses ${SLOT_WORDS[one.slot]}, but nothing fills it`)),
        ...chosen.flatMap((extension) => extension.needs
            .filter((id) => !chosen.some((e) => e.id === id))
            .map((id) => `${extension.name} needs ${nameOf(id)}, which is not installed`)),
    ];
}
function chosenKits(company, available, problems) {
    return company.kits.flatMap((id) => {
        const kit = available.kits.find((k) => k.id === id);
        if (kit)
            return [kit];
        problems.push(`there is no kit "${id}"`);
        return [];
    });
}
function withKit(product, kit) {
    return {
        ...product,
        kit: kit.id,
        commands: { ...kit.commands, ...product.commands },
    };
}
// The products' parts and the extensions' parts, each knowing the backend
// it needs. Products are found in folder order: their parts go after what
// they need.
function allParts(products, kits, extensions) {
    return inStartOrder(withBackendAddress([
        ...products.flatMap((product) => partsOf(product, kits)),
        ...extensions.flatMap((extension) => extension.parts),
    ]));
}
function partsOf(product, kits) {
    return kits.find((kit) => kit.id === product.kit)?.partsFor(product) ?? [];
}
function dependencyProblems(products) {
    const ids = new Set(products.map((product) => product.id));
    return products.flatMap((product) => product.dependsOn
        .filter((id) => !ids.has(id))
        .map((id) => `"${product.id}" needs "${id}", which is not one of the products`));
}
